namespace PropGenerator.Nature.Cliffs;

/// <summary>The panel's hover text for each slab cliff setting, in this app's own words.</summary>
public static class CliffTooltips
{
    private static readonly Dictionary<string, string> Texts = new(StringComparer.Ordinal)
    {
        ["width"] = "How far the cliff spreads from left to right, in metres, from 2 to 60. The blocks share the width, and the planes are laid out again at the new size rather than stretched. The Tall cliff is 6.5 m wide, the Cliff top 14 m and the Long cliff 28 m.",
        ["height"] = "How tall the cliff stands above the ground line, in metres, from 1 to 40. Low ledges are 2 to 5 m, the Long cliff 9 m and the Tall cliff 13 m.",
        ["depth"] = "How far the cliff runs from front to back, in metres, from 1 to 25. The Tall cliff is 3.5 m deep, the Long cliff 6 m and the Cliff top 8 m. No block is ever thinner than 0.6 m, or a third of Depth when that is less.",
        ["blocks"] = "How many slab blocks stand side by side along the width, a whole number from 1 to 12. Neighbours always overlap by at least a fifth of the narrower one, so the run is one solid rock. The Tall cliff has 2, the Cliff top 3 and the Long cliff 5.",
        ["block-variety"] = "How much the blocks differ from each other in width, height, depth and how far they are set forward or back, from 0 to 1. 0 makes them alike; the Long cliff, the Tall cliff and the Cliff top use 0.5 and the Layered cliff 0.6, and 1 gives a ragged run.",
        ["tiers"] = "How many levels are stacked up, a whole number from 1 to 4. Each tier is lower than the one below, set back from it and resting sunk into it, as on the crest of a slope. Most starting points use 1; the Cliff top uses 3.",
        ["layers"] = "How many horizontal plates each block is cut into, a whole number from 0 to 12, each slightly shifted, turned and inset like stacked limestone. 0 leaves the blocks whole; the Layered cliff uses 7.",
        ["layer-variety"] = "How much the plates differ in thickness, from 0 to 1: 0 makes them all alike and 1 lets them vary by up to half. It only matters when Layers is above 0; the Layered cliff uses 0.7.",
        ["joint-crack"] = "How wide the crack is where two blocks side by side meet, in metres, from 0 to 0.2: the blocks join hard, and a narrow V opens along the line where their faces meet, closing to nothing about three quarters of its width deep. 0 leaves a bare, sharp seam. Where the faces run on flush there is no line to crack along, and a crack the mesh is too coarse to show (narrower than two of its cells: a quarter of a metre at Detail 8, an eighth at Detail 16) fades to a bare seam, as it does on the lower detail levels. The starting points use 0.08.",
        ["lean"] = "How far the front faces batter back toward the top, in degrees, from -10 to 30; the back and the ends stay near upright. Negative values overhang a little, and the cliff still stands on its whole base. Every block's top keeps at least the least thickness, so a steep lean on a thin cliff is held back. 5 to 10 degrees reads as a weathered face; the starting points use 8, the Tall cliff 5.",
        ["top-tilt"] = "How far each block's top tilts away from level, in degrees, from 0 to 60, each in its own seeded direction. 0 keeps the tops flat; 3 to 6 degrees looks natural, and the Long cliff and the Cliff top use 4, the Layered cliff 7 and the Tall cliff 12. Steep tilts, with Taper, make a pointed spire. Only the top blocks tilt past 25 degrees: a block another rests on tilts at most 25, and plates at most 4, so they stack flat. A top is also held back from tilting so far that its block would be thinner than its least thickness.",
        ["taper"] = "How much the top blocks narrow toward their top, from 0 to 0.6, as a share of their depth front to back and, at the two ends of the row, of their width end to end: the top block of each column (its top plate, on its top tier) narrows straight from its own base up to its top, half of it at the front and half at the back, beyond any lean. With a steep Top tilt it makes a spire. 0 keeps the sides as they are; 0.2 to 0.4 gives a tapering crest. A taper never leaves a block's top thinner than its least thickness (0.6 m, or a third of Depth when that is less) and a fifth more: on a narrow block the slider stops changing it there. The starting points use 0.",
        ["end-turn"] = "How far the end blocks turn their outer end faces back toward the front, in degrees, from 0 to 50, so the row's front corners break away like rock instead of ending square. This is the most an end turns: each end draws its own turn, from two fifths of it to all of it. A turn is also held to what the block's width allows (at most 40 percent of its width cut off at the front). 0 leaves square end corners, as most of the hand-made pieces have; 5 to 15 degrees breaks them a little, and the starting points use 50.",
        ["foot"] = "How much the blocks standing on the ground narrow toward the ground line, from 0 to 0.4, as a share of their depth front to back and, at the two ends of the row, of their width end to end, so the cliff stands on a foot narrower than its body, undercut like the hand-made pieces. The narrowing runs straight from the top of those blocks down to the ground line, half of it at the front and half at the back, adds to any lean, and goes on below the ground line. 0 stands the cliff on its whole base; 0.1 to 0.25 reads as an undercut foot. A foot never leaves a block's base, down to the bottom of its sunk part, thinner than its least thickness (0.6 m, or a third of Depth when that is less) and a fifth more: past that the slider changes nothing. The starting points use 0.",
        ["underside-tilt"] = "How far the cliff's bottom tilts, in degrees, from 0 to 30: one plane under all the blocks standing on the ground, rising from the cliff's lowest corner toward a seeded direction (the seed picks which way), so the underside slants up out of the ground like a slab settled on one edge. The cliff still rests on the ground, sunk Sink below it, on a strip about 0.3 m wide at that low corner. It is held so the bottom rises at most half the height of the blocks on the ground across the whole cliff, so a long cliff tilts less, and it never leaves a block thinner than its least thickness, so on a cliff under about 0.6 m deep it does nothing. 0 keeps the bottom flat; 5 to 15 degrees reads as a slab settled on one edge, as the hand-made cliffs are, and the starting points use 0.",
        ["faces"] = "How many flat side planes surround each block's footprint, a whole number from 4 to 16. Few faces give a blocky, squared slab; more faces give a rounder one. The starting points use 8.",
        ["roughness"] = "How far each side plane may be set in from the footprint, in metres, from 0 to 1.5, by a seeded amount, so the faces break at uneven angles instead of tracing a smooth outline. 0 keeps the outline even; 0.2 to 0.5 m suits a cliff, and the starting points use 0.3 and the Cliff top 0.5. It is held to a tenth of the mean block width and of Depth, so the faces never set in far enough to thin a block: on the Long cliff, past about 0.55 m the slider changes nothing.",
        ["bevel"] = "How far the flat chamfers across the top and bottom rims of each block cut in, in metres, from 0 to 1.5. 0 leaves square rims; 0.2 to 0.5 m reads as weathered stone, and the starting points use 0.3. It is held to a tenth of each block's smallest size (its width, depth or height), so a small block keeps its top: on the Long cliff, past about 0.7 m the slider changes nothing.",
        ["sink"] = "How far the flat bottom lies below the ground line, in metres, from 0 to 2, so the cliff can sit on uneven terrain without showing a gap. The pivot stays at the ground line. 0 rests the bottom on it; the starting points use 0.5.",
        ["steps"] = "How many step cuts each block takes out of its top, on average, a whole number from 0 to 8: a lowered top and an upright wall, so part of the top drops down a step. The seed changes each block's count by up to one. The starting points use 2, the Layered cliff 3 and the Cliff top 4.",
        ["bites"] = "How many bites each block takes out of its upright corners, on average, a whole number from 0 to 8: a side pushed in and a cross plane, like a corner broken away. The seed changes each block's count by up to one. The starting points use 2, the Tall cliff 1 and the Cliff top and Layered cliff 3.",
        ["grooves"] = "How many grooves each block has along a face, on average, a whole number from 0 to 4: a shallow wedge, so one part of the face stands proud of the other behind an upright step. The seed changes each block's count by up to one. The starting points use 1, the Cliff top 2.",
        ["cut-depth"] = "How deep the steps, bites and grooves go, from 0 to 1, as a share of the most a cut may take: 40 percent of the block's thickness where it cuts. 0 only grazes; the starting points use 0.6 (the Tall cliff 0.45), and 1 cuts as deep as the limit allows.",
        ["chisel"] = "Dresses the whole surface into broad flat facets that meet at crisp straight creases, like stone worked with a chisel, so light breaks across it in planes instead of soft smears. This is how deep the facets cut in, in metres, from 0 to 0.5; 0 leaves the surface as it is. 0.05 to 0.15 reads clearly on a 10 m cliff, and it never cuts deeper than a quarter of Chisel size (past that the slider changes nothing), so the facets stay broad planes. One pattern runs across every block, and it fades out toward the ground line so the cliff still stands on its whole base. The starting points use 0.03, so the faces read as broad flats, as the hand-made cliffs' do.",
        ["chisel-size"] = "How broad each chiselled facet is, in metres, from 0.2 to 5. Small values chip the stone into many little planes; large values give a few big planar cuts. 1 to 3 m suits a 10 m cliff, and the starting points use 2.5. It also limits how deep Chisel can cut, to a quarter of this size. It only matters when Chisel is above 0.",
        ["edge-chips"] = "Knocks flat chips off the cliff's edges and corners, so the rims break in angular facets like hard, broken stone instead of running in a smooth line. Each stretch of an edge, about Chip size long, is either left whole or loses its corner to one flat cut at its own angle, with sharp sides where it meets the next. This is how deep the deepest chips reach into an edge, in metres, from 0 to 1; 0 leaves the edges as they are, and none shows where blocks side by side join. 0.15 to 0.4 suits a 10 m cliff; the starting points use 0.3 (the Layered cliff 0.25). No chip is cut under two mesh cells deep or long: on a coarse mesh the chips' depths are spread from two cells to Edge chips, and where Edge chips is under two cells (the lower detail levels) there are none. A chip is never deeper than 1.5 times Chip size.",
        ["chip-size"] = "How long each chip along an edge is, in metres, from 0.1 to 3. Small values nibble the rims into many little flakes and large values break off a few long spalls; 0.4 to 1.5 m is typical, and the starting points use 1.5, for a few broad breaks like the hand-made cliffs'. It also limits how deep Edge chips can cut, to 1.5 times this size. It only matters when Edge chips is above 0.",
        ["edge-wear"] = "Gnaws the edges and corners unevenly, so the outline wobbles instead of running in straight lines. This is how deep the wear reaches, in metres, from 0 to 1. The starting points use 0.15 (the Layered cliff 0.08), so the edges stay crisp; 0.5 is a clear effect.",
        ["wear-width"] = "How far in from each edge the wear spreads, in metres, from 0.1 to 3. The starting points use 0.8 m. It only matters when Edge wear is above 0.",
        ["wear-size"] = "How big each worn lump is along the edge, in metres, from 0.1 to 5. Small values give fine nibbling and large values give broad dents; 0.8 to 2 m is typical, and the starting points use 2.",
        ["smudge"] = "Soft, uneven pushing and pulling of the surface, stretched up and down like sculpted smears, in metres, from 0 to 1.5. The starting points use 0.02, so the faces stay broad and flat; 0.25 gives a subtle unevenness.",
        ["smudge-size"] = "How big each smear is, in metres, from 0.3 to 10. Small values give many little dents and large values give a few broad swells; the starting points use 5 m.",
        ["creases"] = "How many deep upright cracks run down through the cliff, splitting it into slabs, a whole number from 0 to 4. 0 has none; the starting points use 1.",
        ["crease-depth"] = "How deep each crack cuts in, in metres, from 0 to 2. Around 0.2 to 0.35 reads as a clear crack, and the starting points use 0.2 (the Layered cliff 0.12); larger values cut a canyon. A crack is never deeper than 1.5 times its width (Crease width, or the narrowest groove the mesh can show where that is wider), so a narrow crack stops deepening there instead of folding into a slit.",
        ["crease-width"] = "How wide each crack is at the surface, in metres, from 0.05 to 2. Narrow values read as a sharp split and wide ones as a soft groove; the starting points use 0.1. It also sets how wide the ledges are.",
        ["crease-step"] = "Sets the rock on one side of each crack back from the other, in metres, from 0 to 1.5, so the cliff reads as separate slabs. 0 keeps both sides level.",
        ["crease-angle"] = "How far the cracks turn away from running square to the faces, in degrees, from 0 to 90. 0 keeps them upright across the width; the default is 10 degrees.",
        ["crease-wobble"] = "How much each crack wanders off a straight line, in metres, from 0 to 1.5. 0 draws ruler-straight cracks; 0.15 to 0.25 looks natural, and the starting points use 0.15.",
        ["crease-seed"] = "A whole number from 0 to 9999 that picks a different layout for the cracks only, without changing the blocks, cuts or anything else. Change it until the cracks sit where you like them; the starting points use 31.",
        ["ledges"] = "How many horizontal breaks cross the cliff, each with a small step, like stacked layers, a whole number from 0 to 3. 0 has none.",
        ["ledge-depth"] = "How deep each horizontal break cuts in, in metres, from 0 to 2. The default is 0.3 m. Like a crack, a break is never deeper than 1.5 times its width (Crease width sets it). It only matters when Ledges is above 0.",
        ["ledge-step"] = "Sets the rock above or below each break back, in metres, from 0 to 1.5. The default is 0.2 m; 0 makes a groove with no step.",
        ["lines"] = "How many thin horizontal lines run around the sides, like rock layers, a whole number from 0 to 40. 0 has none; 10 to 20 gives clear strata.",
        ["line-depth"] = "How deep the thin lines are cut, in metres, from 0 to 0.5. The default is 0.05 m. A line is never deeper than 1.5 times its width (fewer lines over the height are wider), so a fine line stops deepening there instead of folding into a slit, and lines packed closer than the mesh can show (about four mesh cells apart) fade out, as on the lower detail levels of a big cliff. It only matters when Lines is above 0.",
        ["line-wobble"] = "How wavy the lines are, from 0 to 10. 0 keeps them level and straight; the default is 2 for a gentle wave.",
        ["detail"] = "How many mesh points there are for every metre of the surface, from 2 to 24. Higher values show finer facets and cracks but make a heavier mesh; 8 is a good middle, and the full-detail mesh is lowered for very large cliffs.",
        ["sharp-angle"] = "Edges that bend more than this many degrees are drawn crisp, and gentler ones are shaded smooth, from 5 to 90 degrees. The default is 30 degrees, so the chips' flat cuts are drawn crisp; lower values make more of the surface look faceted.",
        ["palette"] = "The stone's colour range from shadow to highlight: lavender, slate, granite, sandstone, redrock, basalt or frost. Granite is the default and suits the Long cliff and the Cliff top, slate the Tall cliff and lavender the Layered cliff.",
        ["variation"] = "How much the colour drifts across the cliff in broad patches, from 0 to 1: 0 keeps it even and 1 makes it patchy. The patches follow the rock, not the blocks, so no colour line shows where blocks meet. The default is 0.5.",
    };

    /// <summary>The hover text for one slab cliff setting.</summary>
    /// <param name="key">The setting name, such as "top-tilt".</param>
    /// <returns>A few sentences ending with a full stop: what the setting does, its unit and range, typical values.</returns>
    /// <exception cref="ArgumentException">There is no setting with that name.</exception>
    public static string For(string key) => Texts.TryGetValue(key, out string? text)
        ? text
        : throw new ArgumentException($"No cliff tooltip for '{key}'.", nameof(key));
}
